with base as (select *, case when event_type in ('add_to_cart', 'search') then 'Group A' else 'Other' end event_type_group from web_events where page is not null and event_type <> 'purchase'), flagged as (select *, case when lag(event_time) over (partition by session_id order by event_time, id) is null or event_time > lag(event_time) over (partition by session_id order by event_time, id) + interval 7 days then 1 else 0 end as is_new_burst from base), islands as (select *, sum(is_new_burst) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as burst_id from flagged), with_windows as (select *, count(is_new_burst) over w_hist last4_count_is_new_burst, max(is_new_burst) over w_hist last4_max_is_new_burst, sum(is_new_burst) over w_hist last4_sum_is_new_burst from islands window w_hist as (partition by session_id order by event_time, id rows between 3 preceding and current row)), deduped as (select *, row_number() over (partition by page order by is_new_burst desc, id) as dedup_rank from with_windows qualify dedup_rank = 1), remaining_keys as (select id, event_type from deduped intersect select id, event_type from web_events where page in ('/cart', '/checkout', '/home')), verified as (select s.* from deduped s inner join remaining_keys k on s.id = k.id and s.event_type = k.event_type), cleaned as (select session_id, event_time, duration_sec, event_type_group, burst_id, last4_count_is_new_burst, last4_max_is_new_burst, last4_sum_is_new_burst, dedup_rank, floor(dedup_rank) dedup_rank_whole from verified where event_time > to_date('2023-09-06') and page is distinct from '/home') select burst_id, count(*) as cnt, count(distinct session_id) as distinct_session_ids, count(*) as row_count, max(event_time) as last_seen, approx_percentile(last4_count_is_new_burst, array(0.25, 0.5, 0.75)) as last4_count_is_new_burst_quartiles, count(distinct session_id) as distinct_session_ids_2 from cleaned group by burst_id order by burst_id
